{"cards": [{"node_code": "N_f2eaac7b2a4b1d15", "definition": "研究半导体能带结构、费米能级位置及温度对载流子平衡浓度的影响，涵盖本征/非本征半导体掺杂特性及载流子统计分布规律。", "boundary": "聚焦于热平衡状态下载流子浓度的确定及其与能带参数（禁带宽度、有效态密度）的定量关系。包括掺杂类型（N/P型）对费米能级移动的影响及杂质能级模型。若内容涉及非平衡载流子产生/复合动力学或电场下的输运动力学，则不在此列。", "includes": ["本征载流子浓度与禁带宽度的关系", "掺杂半导体中费米能级与载流子浓度的计算", "温度对载流子浓度及杂质电离的影响"], "excludes": ["载流子在电场或浓度梯度下的漂移/扩散运动", "载流子非平衡产生与复合过程的动力学分析"], "sibling_distinctions": [{"other_code": "N_1f1582248c50635f", "rule": "本节点关注平衡态下载流子浓度的静态分布及能带参数；兄弟节点关注非平衡态下载流子在外场或浓度梯度驱动下的动态输运过程。"}, {"other_code": "N_b9ae44607d1f13e5", "rule": "本节点关注平衡载流子浓度的确定；兄弟节点关注非平衡载流子通过复合机制消失的速率及少子寿命。"}], "cross_boundary_rule": "若研究重点在于确定特定掺杂和温度下的平衡载流子浓度，归入本节点；若重点在于载流子随时间或空间的动态变化（如扩散方程求解），归入漂移与扩散输运机制。"}, {"node_code": "N_1f1582248c50635f", "definition": "研究半导体中载流子在电场作用下的漂移运动及在浓度梯度作用下的扩散运动，涵盖迁移率、扩散系数及爱因斯坦关系等输运参数。", "boundary": "聚焦于载流子在外场或浓度梯度驱动下的宏观/微观输运动力学。包括漂移电流密度、扩散电流密度的表达式，迁移率与温度/掺杂的关系，以及连续性方程的建立。若内容仅涉及平衡态浓度计算或复合机制细节，则不在此列。", "includes": ["电场驱动下的载流子漂移电流与迁移率模型", "浓度梯度驱动下的载流子扩散电流与扩散系数", "爱因斯坦关系及载流子连续性方程"], "excludes": ["热平衡状态下载流子浓度的静态计算", "载流子通过辐射或非辐射过程复合消失的机制"], "sibling_distinctions": [{"other_code": "N_f2eaac7b2a4b1d15", "rule": "本节点关注载流子的动态输运过程（漂移/扩散）；兄弟节点关注平衡态下载流子浓度的静态分布及能带参数。"}, {"other_code": "N_b9ae44607d1f13e5", "rule": "本节点关注载流子的空间移动与输运；兄弟节点关注载流子的产生与消失（复合）过程及其时间尺度。"}], "cross_boundary_rule": "若研究重点在于载流子如何随电场或浓度梯度移动（电流形成），归入本节点；若重点在于载流子如何通过与晶格/杂质相互作用而消失（复合），归入载流子复合与寿命。"}, {"node_code": "N_b9ae44607d1f13e5", "definition": "研究半导体中电子与空穴通过辐射或非辐射过程复合消失的机制，涵盖直接/间接复合、俄歇复合及少子寿命的测量与理论模型。", "boundary": "聚焦于非平衡载流子的消失过程及其时间特性。包括带间复合、带-能级复合（Shockley-Read-Hall）、俄歇复合等机制，以及少子寿命对器件开关速度的影响。若内容涉及载流子的平衡浓度或外场下的输运动力学，则不在此列。", "includes": ["直接复合、间接复合（SRH）及俄歇复合机制", "少子寿命的定义、测量方法及影响因素", "复合率与载流子浓度、温度及缺陷密度的关系"], "excludes": ["热平衡状态下载流子浓度的计算", "载流子在电场或浓度梯度下的漂移/扩散输运过程"], "sibling_distinctions": [{"other_code": "N_f2eaac7b2a4b1d15", "rule": "本节点关注非平衡载流子的消失（复合）过程；兄弟节点关注平衡态下载流子浓度的确定。"}, {"other_code": "N_1f1582248c50635f", "rule": "本节点关注载流子的产生与消失（复合）动力学；兄弟节点关注载流子的空间移动（漂移/扩散）动力学。"}], "cross_boundary_rule": "若研究重点在于载流子如何通过相互作用消失及其时间常数（寿命），归入本节点；若重点在于载流子如何随外场移动形成电流，归入漂移与扩散输运机制。"}]}
